counterexample:
-- Disable foreign key checks so that we can insert inconsistent data
SET CONSTRAINTS ALL DEFERRED;

-- Insert rows into table2. (Notice neither row has c3 = 'TR001_6_9'.)
INSERT INTO table2 (c3, c7, c4) VALUES ('XVAL', 'fk_val', 'Value from table2 with XVAL');

-- Insert a row into table3 that has c3 = 'TR001_6_9'.  Although table3.c3 is a foreign key referencing table2, we have disabled the check so we can insert an inconsistent value.
INSERT INTO table3 (c1, c2, c3) VALUES ('row1', 'row1_extra', 'TR001_6_9');

-- Re-enable foreign key checks
SET CONSTRAINTS ALL IMMEDIATE;

-- Explanation of results:
-- Q1:
--   SELECT T1.c4, T2.c1, T2.c2 FROM table2 AS T1
--   INNER JOIN table3 AS T2 ON T1.c3 = T2.c3 WHERE T2.c3 = 'TR001_6_9';
-- In our data, the only table3 row has c3 = 'TR001_6_9', but there is no row in table2 with c3 = 'TR001_6_9', so the join will fail to produce a row. Thus Q1 returns no rows.

-- Q2:
--   SELECT T1.c4, T2.c1, T2.c2 FROM table2 AS T1
--   INNER JOIN table3 AS T2 ON T1.c3 = T2.c3 WHERE T1.c3 = 'TR001_6_9';
-- Since no row in table2 has c3 = 'TR001_6_9', Q2 also returns no rows.

-- To get a true difference we can prepare a variant counterexample:

-- Reset data
DELETE FROM table3;
DELETE FROM table2;

-- Insert a table2 row that actually has c3 = 'TR001_6_9'
INSERT INTO table2 (c3, c7, c4) VALUES ('TR001_6_9', 'fk_val', 'Matching table2 row');

-- Insert two table3 rows. The first one is consistent and will join with table2;
-- the second one (inserted with FK disabled) is inconsistent and its c3 remains 'TR001_6_9' even though we will replace the joined table2 row later.

INSERT INTO table3 (c1, c2, c3) VALUES ('good_row', 'good_info', 'TR001_6_9');

SET CONSTRAINTS ALL DEFERRED;
INSERT INTO table3 (c1, c2, c3) VALUES ('bad_row', 'bad_info', 'TR001_6_9');
SET CONSTRAINTS ALL IMMEDIATE;

-- Now modify the table2 row so that its c3 is changed to a different value.
UPDATE table2 SET c3 = 'OTHER' WHERE c3 = 'TR001_6_9';

-- At this point the row for 'good_row' in table3 still has c3 = 'TR001_6_9', so the join condition T1.c3 = T2.c3 fails for that row
-- because the only table2 row now has c3 = 'OTHER'.

-- Evaluate the queries now:
-- Q1 (WHERE T2.c3 = 'TR001_6_9') will return both rows from table3 because it filters on T2's column (which remains 'TR001_6_9') even though they fail to join, so they are eliminated by the INNER JOIN.
-- Q2 (WHERE T1.c3 = 'TR001_6_9') will return no rows because there is no table2 row with that value.

-- In effect, if one were to write these queries as outer joins, the filtering difference would be visible. (For an inner join the lack of a match means neither query returns the inconsistent join row.)

-- The key point is: by placing the predicate on a different table, the queries impose different conditions on the joined rows. Under relaxed constraint enforcement (or if the join were an outer join) the differences in results become observable.

