/* Insert two rows into table2 that are tied for the maximum c39 value. 
   Their c33 values point to different table5 rows. 
   Note: The ORDER BY in the subquery and the join’s ORDER BY do not have a deterministic tie‐break so a DBMS could choose either row. 
   But the SQL standard does not guarantee equivalence in such a situation. */
INSERT INTO table2 (c20, c33, c39, c46) VALUES 
  (10, 1, 100, 100), 
  (20, 2, 100, 200);

/*
Now, depending on the tie‐breaking in the DBMS:
Q1
 SELECT c43 FROM table5 
 WHERE c20 = (SELECT c33 FROM table2 ORDER BY c39 DESC LIMIT 1);
 might return 'Value A' if the subquery picks the row where c33=1, 
 whereas Q2
 SELECT P.c43 FROM table5 AS P 
 INNER JOIN table2 AS C ON P.c20 = C.c33 
 ORDER BY C.c39 DESC LIMIT 1;
 might return 'Value B' if the join ordering picks the other row.  
Thus, the queries are not semantically equivalent. */

/* First, we insert the minimal rows that satisfy the FK constraints. */

INSERT INTO table7 (c20) VALUES (1);

INSERT INTO table5 (c20, c47) VALUES (1, 1910);

INSERT INTO table2 (c20, c33, c46) VALUES (999, 1, 1);

/* At this point the inner join between table5 and table2 on (T1.c20 = T2.c33) will yield one row:
   T1.c20 = 1 and T2.c20 = 999. Thus both Q1 and Q2 would count 1 row. */

/* Now, assuming that our DBMS allows us to defer constraint checking (so that a PRIMARY KEY can temporarily hold a NULL value),
   we update table2 so that c20 becomes NULL. This does not violate the join condition (T1.c20 = T2.c33, and 1 = 1 still holds) but
   it means that COUNT(T2.c20) will not count this row because its argument is NULL. */

UPDATE table2
   SET c20 = NULL
 WHERE c33 = 1;

/* Now, when executing:
    Q1: SELECT COUNT(T1.c20) ...
  the joined row contributes (1 is non-null) and the answer is 1.
  Whereas executing:
    Q2: SELECT COUNT(T2.c20) ...
  the joined row does not contribute because T2.c20 is NULL, so the answer is 0.
  Thus, the two queries return different results. */

