counterexample:
-- Insert a Marvel hero in table9 and table7
INSERT INTO table9 (c14, c17) VALUES (1, 100);

INSERT INTO table7 (c14, c18) VALUES (100, 'Marvel Comics');

-- Insert two power records in table10
INSERT INTO table10 (c14, c16) VALUES (10, 'Super Strength');
INSERT INTO table10 (c14, c16) VALUES (11, 'X-Ray Vision');

-- Insert two rows in table6 for the same hero
-- one associating the hero with the Super Strength power
INSERT INTO table6 (c13, c15) VALUES (1, 10);
-- the other associating the same hero with a different power
INSERT INTO table6 (c13, c15) VALUES (1, 11);

-- To see the effect of duplicate‐join, add a second Marvel hero
INSERT INTO table9 (c14, c17) VALUES (2, 200);
INSERT INTO table7 (c14, c18) VALUES (200, 'Marvel Comics');
-- This hero has only one power record, and that power is Super Strength
INSERT INTO table10 (c14, c16) VALUES (12, 'Super Strength');
INSERT INTO table6 (c13, c15) VALUES (2, 12);

-- When the queries are run over these rows, the fact that hero 1 appears twice in the join
-- (with one row “good” and one “bad”) but hero 2 appears once causes a different overall percentage
-- to be computed by Q1 versus Q2.

