INSERT INTO table9(c14, c22, c10, c7, c11, c21, c20, c17, c2) 
VALUES (1, 'Result1', 102, 101, 103, 106, 105, 104, 100);

-- Insert rows into table10. 
-- One row keyed by 1 with c16 not equal to 'Adaptation'
-- Another row keyed by 2 with c16 = 'Adaptation'

INSERT INTO table10(c14, c16) VALUES (1, 'Not Adaptation');
INSERT INTO table10(c14, c16) VALUES (2, 'Adaptation');

-- Insert a row into table6 that links table9 and table10
-- c13 refers to table9.c14 (1) and c15 refers to table10.c14 (2)

INSERT INTO table6(c13, c15) VALUES (1, 2);

-- Explanation of the effect:
-- In Q1 (with join condition ON T2.c15 = T3.c14), table6 tells us to use key 2 in table10 which has c16 = 'Adaptation', so the row from table9 (with c22 = 'Result1') is returned.
-- In Q2 (if mistakenly joining ON T1.c14 = T3.c14), it would join table10 using key 1 from table9, and since table10.c16 for key 1 is 'Not Adaptation', the WHERE clause fails and no row is returned.

