-- Insert two rows into table11
-- This row has c38 = 1 and c17 = '10'. Because table10 has two copies of c38 = 1, it will be joined twice in Q1.
INSERT INTO table11(c40, c38, c12, c5, c20, c33, c32, c30, c22, c17, c43) 
VALUES (1, 1, 1, 1, 0, 'a', 0, 0.0, 0, '10', 1);

