INSERT INTO table11(c40, c38, c12, c5, c20, c33, c32, c30, c22, c17, c43) 
VALUES (2, 2, 1, 1, 0, 'a', 0, 0.0, 0, '30', 1);

/*
Query Q1 (with the join) will join the table11 row with c38 = 1 twice (because table10 has two rows for c38 = 1) and the row with c38 = 2 once. 
Thus it computes the average over the values: 10, 10, and 30, i.e. (10+10+30)/3 = 50/3 ≈ 16.67.

Query Q2 (using IN) obtains the set {1,2} from table10 (duplicates eliminated) and then selects the two table11 rows, averaging 10 and 30, i.e. (10+30)/2 = 20.

This difference (16.67 versus 20) shows that Q1 and Q2 are not semantically equivalent under duplicate-producing circumstances.
*/

/* First, insert the minimal rows needed to satisfy foreign keys */

-- table1: two rows used by table10
INSERT INTO table1 (c2, c3, c27, c47) VALUES (1, 'one', 'A', 'x');
INSERT INTO table1 (c2, c3, c27, c47) VALUES (2, 'two', 'B', 'y');

-- table12: needed for table10.fk on c49
INSERT INTO table12 (c49, c47) VALUES (101, 'r1');
INSERT INTO table12 (c49, c47) VALUES (102, 'r2');

-- table10: two rows that will join
