-- Now insert rows into table11. All rows satisfy the join filters (c43 = 3 and c38 = 1).
-- The first row has a non-NULL value for c12 (group key = 100).
INSERT INTO table11 (c40, c38, c12, c5, c20, c33, c32, c30, c22, c43)
VALUES (1, 1, 100, 1, 1, 'dummy', 1, 1.0, 1, 3);

-- The next two rows have NULL in c12. (This might occur if, for example, a data‐quality error led to a NULL even though the column is supposed to be NOT NULL.)
-- These two rows will be grouped together with the NULL key.
INSERT INTO table11 (c40, c38, c12, c5, c20, c33, c32, c30, c22, c43)
VALUES (2, 1, NULL, 1, 1, 'dummy', 1, 1.0, 1, 3);

INSERT INTO table11 (c40, c38, c12, c5, c20, c33, c32, c30, c22, c43)
VALUES (3, 1, NULL, 1, 1, 'dummy', 1, 1.0, 1, 3);

/*
Explanation of what happens:
  • For the group with T1.c12 = 100:
      - Q1 will compute COUNT(T1.c12) = 1 and Q2 will compute COUNT(*) = 1.
  • For the group with T1.c12 = NULL:
      - Q1’s COUNT(T1.c12) ignores NULLs and returns 0 (even though there are 2 rows in that group),
      - Q2’s COUNT(*) returns 2.
Since the queries group by T1.c12 and then order by the COUNT descending and take the top result (LIMIT 1), Q1 would return 1 (the maximum count among its groups) while Q2 would return 2. This demonstrates that despite the apparent similarity of filters, the two queries are not semantically equivalent.
*/

