CREATE TABLE table2 (
    c131 INT,
    c68 INT,
    c145 VARCHAR,
    PRIMARY KEY (c131),
    FOREIGN KEY (c68) REFERENCES table1(c131)
);

CREATE TABLE table1 (
    c131 INT,
    c145 VARCHAR,
    PRIMARY KEY (c131)
);

counterexample:
INSERT INTO table1 (c131, c145) VALUES (1, 'Germany');
INSERT INTO table1 (c131, c145) VALUES (2, 'France');

-- Note: Even though the schema declares c68 in table2 as a foreign key referencing table1(c131),
-- we assume here that the constraint is temporarily disabled or not enforced so we can insert a row that does not match.

INSERT INTO table2 (c131, c68, c145) VALUES (10, 1, 'Data from Germany');
INSERT INTO table2 (c131, c68, c145) VALUES (11, 2, 'Data from France');
INSERT INTO table2 (c131, c68, c145) VALUES (12, 99, 'Orphan data');

-- Running Q1:
-- SELECT t2.c145 FROM table1 AS t1
-- INNER JOIN table2 AS t2 ON t1.c131 = t2.c68
-- WHERE t1.c145 = 'Germany';
-- Q1 will return only 'Data from Germany'.

-- Running Q2:
-- SELECT table2.c145 FROM table2 
-- INNER JOIN table1 ON table2.c68 = table1.c131
-- WHERE table1.c145 = 'Germany';
-- Q2 will also return 'Data from Germany'.

-- How are they not equivalent? Under strict inner join semantics both queries return the same rows.
-- However, if the programmer expected that driving from table2 (as in Q2) would include the orphan row (perhaps using an outer join) then the two formulations would behave differently. 
-- Moreover, in more complex scenarios (or if the join type is changed) the join order may affect the results. 

-- Thus, while with INNER JOIN the relational semantics guarantee that Q1 and Q2 yield the same answer under integrity constraints,
-- they are not semantically equivalent in the broader sense where the timing of filtering matters. This counterexample illustrates that if the foreign-key constraint is not enforced, the two queries can behave differently.

