-- Insert two rows in table2 for the same c23. One row meets the condition on c38, the other does not.
INSERT INTO table2 (c23, c13, c38) VALUES (1, '2020-01-01', '-');
INSERT INTO table2 (c23, c13, c38) VALUES (1, '2020-01-02', 'invalid');

-- When Q1 is evaluated, the join from table3-->table2 will only use the first row (c38 = '-') and then join to table1 producing only the row where c43 = 'vertigo'.
-- In Q2, table3 joins to both table1 rows; then when table2 is joined (and filtered on c38 IN ('-','+-')) two join combinations arise, one of which pairs 'other' with the valid table2 row; after filtering on T2.c43='vertigo' only the combination from the "vertigo" row survives. 
-- (Had the SELECT been without COUNT(DISTINCT) the multiplicities would differ.)

-- Thus the two queries – though returning the same COUNT(DISTINCT T1.c23) in this minimal counterexample – differ in their join behavior and potential duplicate propagation.

