INSERT INTO table8 (c42) VALUES (1);

/* Insert two rows into table7. The row with c29 = 'A' will be referenced by two qualifying table5 rows; the row with c29 = 'B' will be referenced only by a non‐qualifying row. */
INSERT INTO table7 (c29, c19, c21, c41, c24) VALUES ('A', 'first', 'alpha', 1, 't6');
INSERT INTO table7 (c29, c19, c21, c41, c24) VALUES ('B', 'second', 'beta', 1, 't6');

/* Insert three rows into table5. The two rows referencing 'A' have c1 > 40; the row referencing 'B' has c1 <= 40. */
INSERT INTO table5 (c20, c1, c25) VALUES ('row1', 50, 'A');
INSERT INTO table5 (c20, c1, c25) VALUES ('row2', 60, 'A');
INSERT INTO table5 (c20, c1, c25) VALUES ('row3', 30, 'B');

/*
For Q1:
  SELECT T1.c19, T1.c21
  FROM table7 AS T1 INNER JOIN table5 AS T2 ON T1.c29 = T2.c25
  WHERE T2.c1 > 40;
  --> The join produces two pairs for table7 row 'A' (via 'row1' and 'row2') and none for 'B'.

For Q2:
  SELECT T2.c19, T2.c21
  FROM table5 AS T1 INNER JOIN table7 AS T2 ON T1.c25 = T2.c29
  WHERE T1.c1 > 40;
  --> The qualifying table5 rows are 'row1' and 'row2' (since 'row3' fails the filter), so the join yields two pairs (again, both from table7 row 'A').

Depending on whether duplicate elimination is applied, the two queries might return different numbers of identical rows. This difference in bag semantics shows that Q1 and Q2 are not semantically equivalent.
*/

