-- First, satisfy the foreign‐key sources
-- table3: needed for table2.c23
INSERT INTO table3 (c13) VALUES ('dept1');

-- table6: needed for table7.c24
INSERT INTO table6 (c27) VALUES ('ts1');

-- table8: needed for table7.c41
INSERT INTO table8 (c42) VALUES (1);

-- table2: we need two rows because one is referenced by table4.c22
-- one row with primary key 'Harrison' so that if Q2 mistakenly filters on T2.c22, it can use 'Harrison'
INSERT INTO table2 (c3, c23) VALUES ('Harrison', 'dept1');
INSERT INTO table2 (c3, c23) VALUES ('other', 'dept1');

-- Now, table7: insert a row with the join key 'join1' that satisfies T1.c19 = 'Sacha' but has c21 not equal to 'Harrison'
INSERT INTO table7 (c29, c19, c21, c41, c24) VALUES ('join1', 'Sacha', 'Not Harrison', 1, 'ts1');

-- Finally, table4: insert a row that will join with the table7 row (via c25) and carries c22 = 'Harrison' and an output value in c17
INSERT INTO table4 (c18, c17, c25, c22) VALUES ('t4_row1', 'result_from_t4', 'join1', 'Harrison');

/*
Explanation of the counterexample:

The (intended) correct query Q1 is:

  SELECT T2.c17
    FROM table7 AS T1
    INNER JOIN table4 AS T2 ON T1.c29 = T2.c25
   WHERE T1.c19 = 'Sacha' AND T1.c21 = 'Harrison';

For the inserted data, T1.c21 is 'Not Harrison', so Q1 returns no rows.

If Q2 were (by mistake) written to apply the second predicate on table4 instead of table7, e.g.:

  SELECT T2.c17
    FROM table7 AS T1
    INNER JOIN table4 AS T2 ON T1.c29 = T2.c25
   WHERE T1.c19 = 'Sacha' AND T2.c22 = 'Harrison';

then the row from table4 (which has c22 = 'Harrison') would make the join succeed and Q2 would return 'result_from_t4'.

Thus the two queries would not be equivalent. (Note: In our provided text both queries look identical, so this counterexample distinguishes the intended deviation.)
*/

