/* Note: The following INSERTs assume a test scenario where duplicate rows in table1 are allowed, so that the PK constraint is not enforced (or table1 is actually a view that produces duplicates) */

-- Insert duplicate rows into table1 for the same c7 value that both satisfy the condition c13='KAM'
